            CharterBookingRequest.objects.filter(
                event=event, status="PENDING"
            ).aggregate(total=models.Sum("requested_seats"))["total"]
            or 0
        )
        total_seats = event.available_seats or 0
        available = total_seats - confirmed
        upcoming_events.append(
            {
                "event": event,
                "confirmed_seats": confirmed,
                "pending_seats": pending,
                "available_seats": available,
                "total_seats": total_seats,
